{
  "criteria": [
    {
      "kind": "exclusion",
      "text": "Received radiation therapy (or other non-systemic therapy) within 2 weeks before first dose of study treatment on W1D1. Subjects should have recovered (i.e. Grade ≤ 1 or at baseline) from radiation-related toxicities.",
      "quote": "Received radiation therapy (or other non-systemic therapy) within 2 weeks before first dose of study treatment on W1D1.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Treatment with complementary medications (e.g. herbal supplements or traditional Chinese medicines) to treat the disease under study within 2 weeks prior to start of study treatment or at any time during the treatment phase of the study.",
      "quote": "Treatment with complementary medications (e.g. herbal supplements or traditional Chinese medicines) to treat the disease under study within 2 weeks prior to start of study treatment",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Received systemic pharmacologic doses of corticosteroids > 10 mg/day prednisone within 15 days before first dose of study treatment on W1D1.",
      "quote": "Received systemic pharmacologic doses of corticosteroids > 10 mg/day prednisone within 15 days before first dose of study treatment on W1D1.",
      "thresholds": [
        {
          "test": "prednisone dose",
          "op": ">",
          "value": 10,
          "unit": "mg/day"
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "History of immune-mediated AE leading to permanent discontinuation due to prior PD1–blocking antibody.",
      "quote": "History of immune-mediated AE leading to permanent discontinuation due to prior PD1–blocking antibody.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Not fully recovered from AEs due to prior treatment (to Grade 1 or less, per CTCAE), with the exception of persistent vitiligo, alopecia, hypothyroidism, diabetes mellitus, and adrenal and/or pituitary insufficiency.",
      "quote": "Not fully recovered from AEs due to prior treatment (to Grade 1 or less, per CTCAE)",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Active pneumonitis or history of noninfectious pneumonitis that required steroids.",
      "quote": "Active pneumonitis or history of noninfectious pneumonitis that required steroids.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Severe uncontrolled medical disease within 12 months of Screening, including but not limited to poorly controlled hypertension, unstable angina, myocardial infarction, congestive heart failure (New York Heart Association Class II or greater), pericarditis, cerebrovascular accident, or implanted or continuous use of a pacemaker or defibrillator, or emphysema with FEV1 ≤ 50% predicted.",
      "quote": "Severe uncontrolled medical disease within 12 months of Screening, including but not limited to poorly controlled hypertension, unstable angina, myocardial infarction, congestive heart failure (New York Heart Association Class II or greater), pericarditis, cerebrovascular accident, or implanted or continuous use of a pacemaker or defibrillator, or emphysema with FEV1 ≤ 50% predicted.",
      "thresholds": [
        {
          "test": "FEV1",
          "op": "<=",
          "value": 50,
          "unit": "% predicted"
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "Known history of immunodeficiency.",
      "quote": "Known history of immunodeficiency.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Known additional malignancy that is progressing or required active treatment within the past 3 years. Exceptions include cancers that have undergone potentially curative therapy, e.g. basal cell carcinoma of the skin, squamous cell carcinoma of the skin, localized prostate cancer with prostate-specific antigen level below 4.0 ng/mL, in situ cervical cancer on biopsy or a squamous intraepithelial lesion on Papanicolaou smear, and thyroid cancer (except anaplastic), in situ breast cancer, and adjuvant hormonal therapy for breast cancer > 3 years from curative-intent surgical resection.",
      "quote": "Known additional malignancy that is progressing or required active treatment within the past 3 years.",
      "thresholds": [
        {
          "test": "prostate-specific antigen",
          "op": "<",
          "value": 4.0,
          "unit": "ng/mL"
        }
      ]
    },
    {
      "kind": "exclusion",
      "text": "Active autoimmune disease that required systemic treatment in past 2 years; replacement therapy is not considered a form of systemic treatment.",
      "quote": "Active autoimmune disease that required systemic treatment in past 2 years",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Untreated, symptomatic, or enlarging central nervous system (CNS) metastases or carcinomatous meningitis (including leptomeningeal metastases from solid tumors).",
      "quote": "Untreated, symptomatic, or enlarging central nervous system (CNS) metastases or carcinomatous meningitis (including leptomeningeal metastases from solid tumors).",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Prior allogenic tissue/solid organ transplant.",
      "quote": "Prior allogenic tissue/solid organ transplant.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Active infection requiring systemic therapy.",
      "quote": "Active infection requiring systemic therapy.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Known or suspected active infection with severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2).",
      "quote": "Known or suspected active infection with severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2).",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Known or suspected active infection with human immunodeficiency virus, hepatitis B virus, or hepatitis C virus (testing is not required unless suspected).",
      "quote": "Known or suspected active infection with human immunodeficiency virus, hepatitis B virus, or hepatitis C virus (testing is not required unless suspected).",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Received a live virus/attenuated vaccination within 30 days before first dose of study treatment on W1D1.",
      "quote": "Received a live virus/attenuated vaccination within 30 days before first dose of study treatment on W1D1.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Received blood products (including platelets or red blood cells) or colony stimulating factors (including granulocyte colony stimulating factor, granulocyte/macrophage colony stimulating factor, or recombinant erythropoietin) within 3 weeks before the W1D1 visit.",
      "quote": "Received blood products (including platelets or red blood cells) or colony stimulating factors (including granulocyte colony stimulating factor, granulocyte/macrophage colony stimulating factor, or recombinant erythropoietin) within 3 weeks before the W1D1 visit.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "History of permanent discontinuation of cemiplimab due to infusion reactions or hypersensitivity to the investigational agents or their excipients.",
      "quote": "History of permanent discontinuation of cemiplimab due to infusion reactions or hypersensitivity to the investigational agents or their excipients.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Any concurrent uncontrolled illness, including mental illness or substance abuse, which in the opinion of the Investigator would make the subject unable to cooperate or participate in the study.",
      "quote": "Any concurrent uncontrolled illness, including mental illness or substance abuse, which in the opinion of the Investigator would make the subject unable to cooperate or participate in the study.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Participation in another clinical study of an investigational anticancer therapy or device within 30 days before first dose of study treatment on W1D1. Note: Participation in the follow-up phase (receiving no study treatment) of a prior study is allowed.",
      "quote": "Participation in another clinical study of an investigational anticancer therapy or device within 30 days before first dose of study treatment on W1D1.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Requires prohibited treatment (i.e. non-protocol specified anticancer pharmacotherapy, surgery, or conventional radiotherapy) for treatment of malignant tumor.",
      "quote": "Requires prohibited treatment (i.e. non-protocol specified anticancer pharmacotherapy, surgery, or conventional radiotherapy) for treatment of malignant tumor.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Has a life expectancy of less than 3 months and/or has rapidly progressing disease (e.g. tumor bleeding, uncontrolled tumor pain) in the opinion of the treating Investigator.",
      "quote": "Has a life expectancy of less than 3 months and/or has rapidly progressing disease (e.g. tumor bleeding, uncontrolled tumor pain) in the opinion of the treating Investigator.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Received previous vidutolimod treatment.",
      "quote": "Received previous vidutolimod treatment.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Pregnant or breastfeeding or expecting to conceive children within the projected duration of the study, from the time of consent until at least 150 days after last dose of study treatment.",
      "quote": "Pregnant or breastfeeding or expecting to conceive children within the projected duration of the study, from the time of consent until at least 150 days after last dose of study treatment.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Sexually active men and women of childbearing potential who are unwilling to practice highly effective contraception prior to the initial dose/start of the first treatment, during the study, and for at least 6 months after the last dose.",
      "quote": "Sexually active men and women of childbearing potential* who are unwilling to practice highly effective contraception prior to the initial dose/start of the first treatment, during the study, and for at least 6 months after the last dose.",
      "thresholds": []
    },
    {
      "kind": "exclusion",
      "text": "Had major surgeries (including complete oncologic resection) within last 4 weeks prior to enrollment, and/or have not recovered adequately from the toxicities and/or complications from the intervention. Minor surgeries (including routine resections of early stage CSCCs and BCCs that may be due to field cancerization) require a 7-day washout.",
      "quote": "Had major surgeries (including complete oncologic resection) within last 4 weeks prior to enrollment, and/or have not recovered adequately from the toxicities and/or complications from the intervention.",
      "thresholds": []
    }
  ]
}
